insert into public.conhecimento_eda (publico, tema, titulo, palavras, conteudo) values
('visitante','territorio','Rio Negro: águas escuras',ARRAY['rio negro','agua','escura','preta','cor','mosquito','carapana']::text[],'O Rio Negro tem águas escuras, cor de chá, por causa da matéria orgânica das folhas da floresta que se dissolve na água. A água é ácida, e por isso em geral há bem menos mosquitos que nos rios de água barrenta. É um dos maiores rios do mundo em volume.'),
('visitante','territorio','Encontro das Águas',ARRAY['encontro','aguas','solimoes','manaus','misturam']::text[],'Perto de Manaus, o Rio Negro (escuro) encontra o Rio Solimões (barrento) e os dois correm lado a lado por vários quilômetros sem se misturar, por diferenças de temperatura, velocidade e densidade. Dá para ver de barco, saindo de Manaus.'),
('visitante','destino','Barcelos',ARRAY['barcelos','mariua','ornamental','cardinal','capital','historia']::text[],'Barcelos fica no médio Rio Negro e foi a primeira capital da antiga Capitania de São José do Rio Negro, no século XVIII. É conhecida como terra dos peixes ornamentais (como o cardinal) e da pesca esportiva do tucunaré. Em frente à cidade está o Arquipélago de Mariuá, considerado um dos maiores arquipélagos fluviais do mundo.'),
('visitante','destino','Festival do Peixe Ornamental',ARRAY['festival','ornamental','barcelos','janeiro','acara','cardinal']::text[],'Barcelos realiza o Festival do Peixe Ornamental, tradicionalmente em janeiro, com a disputa entre as agremiações do Acará-Disco e do Cardinal, música e apresentações. Datas exatas mudam a cada ano: confirmar com a operadora ou a prefeitura.'),
('visitante','pesca','Pesca esportiva do tucunaré',ARRAY['pesca','pescar','tucunare','temporada','epoca','quando','acu']::text[],'A temporada do tucunaré no médio Rio Negro vai de setembro a março, na seca (águas baixas), com pico de outubro a janeiro. O tucunaré-açu é o troféu mais desejado. No Rio Negro a pesca esportiva é pesque e solte: o peixe é fotografado e devolvido ao rio.'),
('visitante','pesca','Equipamento e licença de pesca',ARRAY['isca','vara','equipamento','licenca','linha','carretilha','molinete']::text[],'Para o tucunaré são comuns varas de ação média a pesada, linhas multifilamento e iscas artificiais de superfície e meia-água (como hélice e zara). Para pescar é exigida a licença de pesca amadora; a operadora orienta como emitir e o que já está incluso no pacote.'),
('visitante','territorio','Cheia e seca do rio',ARRAY['cheia','seca','nivel','igapo','chuva','clima','tempo','mes']::text[],'O Rio Negro sobe e desce vários metros por ano. A cheia costuma ter pico por volta de junho e é ótima para passeios de canoa no igapó (floresta alagada). A seca tem pico por volta de outubro e novembro, quando aparecem praias de areia branca e a pesca fica melhor. Faz calor o ano todo, em geral entre 25 e 33 °C.'),
('visitante','destino','Anavilhanas e Novo Airão',ARRAY['anavilhanas','novo airao','boto','ilhas','parque']::text[],'O Parque Nacional de Anavilhanas, em Novo Airão, protege um dos maiores arquipélagos fluviais do mundo, com centenas de ilhas no Rio Negro. Novo Airão fica a cerca de 3 horas de carro de Manaus e é famosa pelo encontro com os botos-vermelhos.'),
('visitante','destino','Parintins e o Festival',ARRAY['parintins','boi','bumba','garantido','caprichoso','festival','junho','bumbodromo']::text[],'Em Parintins acontece o Festival Folclórico, no fim de junho, no Bumbódromo: a disputa entre o Boi Garantido (vermelho) e o Boi Caprichoso (azul), com toadas, alegorias e lendas amazônicas, entre elas a da Iara.'),
('visitante','cultura','A lenda da Iara',ARRAY['iara','lenda','mae','aguas','sereia','quem e voce','seu nome']::text[],'Na lenda, a Iara é a mãe-d’água: uma moça encantada que vive nos rios e encanta os pescadores com seu canto. O nome vem do tupi e significa algo como senhora das águas. A Iara da Encantos é a guardiã que recebe os visitantes e ajuda a planejar a viagem.'),
('visitante','cultura','Outras lendas amazônicas',ARRAY['boto','curupira','lenda','mito','encantado','mapinguari']::text[],'O boto-cor-de-rosa, na lenda, vira um rapaz elegante de chapéu branco que aparece nas festas. O Curupira, de pés virados para trás, protege a mata e confunde quem a destrói. Essas histórias fazem parte do dia a dia das comunidades ribeirinhas.'),
('visitante','cultura','Comida amazônica',ARRAY['comida','culinaria','comer','prato','tacaca','tambaqui','pirarucu','acai','tucupi','jaraqui']::text[],'Vale provar: tambaqui assado na brasa, pirarucu (inclusive o de casaca), jaraqui frito, tacacá com tucupi e jambu (que faz a boca tremer), açaí servido sem açúcar e farinha d’água. Em Manaus, o sanduíche x-caboquinho, com tucumã e queijo coalho, é tradição.'),
('visitante','natureza','Fauna do Rio Negro',ARRAY['animal','animais','fauna','onca','boto','jacare','macaco','ariranha','passaro','ave','arara','tucano']::text[],'Na região vivem botos-vermelhos e tucuxis, jacarés, ariranhas, diversos macacos, araras, tucanos, garças e o gavião-real. A onça-pintada também habita a floresta, mas avistar uma é raro e sempre uma sorte. Nunca alimente animais silvestres.'),
('visitante','preparo','O que levar',ARRAY['levar','mala','roupa','bagagem','preparar','lista']::text[],'Leve roupas leves e de manga longa (protegem do sol e de insetos), chapéu, óculos de sol, protetor solar, repelente, capa de chuva, sandália ou tênis que possa molhar, saco estanque para celular e documentos, garrafa reutilizável, lanterna e remédios de uso pessoal. Leve documento com foto.'),
('visitante','preparo','Saúde na viagem',ARRAY['vacina','febre amarela','saude','malaria','medico','remedio']::text[],'Para viagens à Amazônia, a vacina contra febre amarela é recomendada e deve ser tomada com pelo menos 10 dias de antecedência. Algumas áreas têm risco de malária: procure um posto de saúde ou médico do viajante antes da viagem. Informe à operadora alergias e restrições pela ficha de saúde do passeio.'),
('visitante','preparo','Segurança na água',ARRAY['seguranca','colete','nadar','barco','lancha','crianca']::text[],'Em embarcações, o colete salva-vidas é obrigatório. Avise a operadora se alguém não sabe nadar, se há crianças ou restrições de saúde: tudo isso entra na ficha de saúde e ajuda a equipe a cuidar de todos.'),
('visitante','logistica','Como chegar a Barcelos e ao Rio Negro',ARRAY['chegar','voo','aviao','barco','recreio','manaus','transporte','aeroporto']::text[],'Manaus é a porta de entrada. Para Barcelos há voos regionais saindo de Manaus, e também barcos regionais, que levam bem mais tempo (em geral mais de um dia rio acima). Muitos pacotes de pesca incluem o traslado: confirme com a operadora.'),
('visitante','destino','Manaus',ARRAY['manaus','teatro','amazonas','mercado','ponta negra','cidade']::text[],'Manaus tem o Teatro Amazonas, símbolo do ciclo da borracha, o Mercado Adolpho Lisboa, a praia da Ponta Negra e é o ponto de partida para o Encontro das Águas, Anavilhanas e o Rio Negro.'),
('visitante','destino','São Gabriel da Cachoeira',ARRAY['sao gabriel','neblina','indigena','alto rio negro','curicuriari','bela adormecida']::text[],'São Gabriel da Cachoeira, no Alto Rio Negro, é o município com maior presença indígena do Brasil, com muitas línguas faladas. Na paisagem se destaca a Serra do Curicuriari, a Bela Adormecida. A região dá acesso ao Pico da Neblina, o ponto mais alto do Brasil, com visitação controlada.'),
('visitante','conduta','Turismo responsável e comunidades',ARRAY['comunidade','ribeirinho','indigena','foto','artesanato','respeito','sustentavel','lixo']::text[],'Ao visitar comunidades, peça permissão antes de fotografar pessoas, respeite costumes e prefira comprar artesanato direto dos artesãos. Traga seu lixo de volta, não alimente animais e siga as orientações do guia: o turismo que respeita a floresta ajuda quem vive nela.'),
('visitante','plataforma','Como reservar pela Encantos',ARRAY['reservar','reserva','preco','valor','pagar','pagamento','confirmar','orcamento','quanto custa']::text[],'A Encantos da Amazônia conecta você às operadoras locais. Preço, vagas e datas são sempre confirmados pela operadora do passeio. Pelo link do passeio você vê os detalhes e o contato público da operadora para combinar e fechar.'),
('operador','plataforma','Cadastrar e publicar passeios',ARRAY['passeio','cadastrar','publicar','portal','foto','experiencia','vitrine']::text[],'Em Passeios > Novo passeio você cadastra nome, categoria, cidade, duração, preço e fotos direto do aparelho. Marcando para publicar no portal, o passeio aparece em Experiências e na Rede do portal público, com preço visível. Fotos boas e descrição clara aumentam o interesse.'),
('operador','plataforma','Reservas e saídas',ARRAY['reserva','saida','guia','embarcacao','horario','confirmar','status']::text[],'Em Reservas > Nova reserva você registra cliente, passeio, data, horário e pessoas. Vincule guia e embarcação para a plataforma checar conflitos e lotação. Reservas sem guia, sem barco ou sem horário aparecem como pendência no Painel.'),
('operador','plataforma','Ficha de saúde (LGPD)',ARRAY['ficha','saude','alergia','participante','convite','lgpd']::text[],'Cada reserva tem o card Participantes e saúde: envie o link da ficha ao turista ou preencha junto. Alertas graves aparecem no Painel antes da saída. Por privacidade, a ficha é apagada 120 dias após a viagem e não é enviada para a IA.'),
('operador','plataforma','Demandas e suprimentos',ARRAY['demanda','suprimento','combustivel','alimentacao','gelo','item','compra']::text[],'Em Demandas você planeja combustível, alimentação, gelo e outros itens, com cálculo por pessoa e por dia. Ligue a demanda à saída para a plataforma conferir se os suprimentos atendem o grupo.'),
('operador','plataforma','Financeiro',ARRAY['financeiro','receita','despesa','pendente','pix','receber','pagar','caixa']::text[],'No Financeiro você lança receitas e despesas, acompanha o que está a receber e a pagar, e vê atrasados. Recebimentos ligados à reserva aparecem também no Painel.'),
('operador','plataforma','Vouchers',ARRAY['voucher','emitir','validar','qr','codigo']::text[],'Em Vouchers você emite o comprovante do passeio para o cliente, com código e QR de verificação. No embarque, valide o voucher para marcar como utilizado.'),
('operador','plataforma','Operação ao vivo',ARRAY['ao vivo','operacao','localizacao','viagem','acompanhar','distancia']::text[],'Em Reservas > Operação ao vivo o gestor acompanha a viagem em curso a distância: posição registrada, eventos e alertas da equipe embarcada.'),
('operador','negocio','Dicas para vender mais',ARRAY['vender','venda','cliente','divulgar','marketing','instagram','preco']::text[],'Responder rápido, publicar fotos reais, deixar preço e o que está incluso bem claros, informar política para crianças e manter as próximas saídas atualizadas faz o passeio aparecer melhor no portal e passar confiança ao turista.'),
('operador','negocio','LGPD na operação',ARRAY['lgpd','privacidade','dados','cpf','documento','proteger']::text[],'Colete só os dados necessários para a viagem, não compartilhe listas de clientes por grupos de mensagem, peça consentimento para enviar novidades e apague dados que não são mais necessários. A plataforma já separa os dados de cada operadora.');
