-- EDA_FASE_A_V1
-- Base de conhecimento da Iara (visitantes) e da EDA (operadores) + cache da
-- recepção inteligente do painel. Tabelas fechadas: só o servidor (service_role) lê/grava.

create table if not exists public.conhecimento_eda (
  id uuid primary key default gen_random_uuid(),
  publico text not null check (publico in ('visitante','operador','ambos')),
  tema text not null,
  titulo text not null check (char_length(titulo) between 2 and 120),
  palavras text[] not null default '{}',
  conteudo text not null check (char_length(conteudo) between 10 and 1500),
  ativo boolean not null default true,
  atualizado_em timestamptz not null default now()
);
alter table public.conhecimento_eda enable row level security;
revoke all on table public.conhecimento_eda from public, anon, authenticated;

create table if not exists public.eda_recepcao (
  usuario_id uuid primary key references auth.users(id) on delete cascade,
  assinatura text not null,
  variacoes jsonb not null default '[]'::jsonb,
  gerado_em timestamptz not null default now()
);
alter table public.eda_recepcao enable row level security;
revoke all on table public.eda_recepcao from public, anon, authenticated;

